import{_ as t,c as s,o as r,ah as o}from"./chunks/framework.RCw5T9E9.js";const c=JSON.parse('{"title":"Update settings","description":"","frontmatter":{"title":"Update settings"},"headers":[],"relativePath":"options/update_settings.md","filePath":"options/update_settings.md"}'),n={name:"options/update_settings.md"};function a(i,e,h,l,g,d){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="update-settings" tabindex="-1">Update settings <a class="header-anchor" href="#update-settings" aria-label="Permalink to &quot;Update settings&quot;">​</a></h1><p>Below <strong>Customize</strong> in <strong>Options → General</strong> you will find <strong>Search Parameters</strong> and <strong>Auto Refresh</strong>. They persist with the rest of the profile (see <a href="/qa-tools/docs/options/settings_management.html">Settings management</a>).</p><hr><h2 id="search-parameters" tabindex="-1">Search Parameters <a class="header-anchor" href="#search-parameters" aria-label="Permalink to &quot;Search Parameters&quot;">​</a></h2><p>Global rules for <strong>text search</strong> on <strong>Props</strong>, <strong>Network</strong>, <strong>Pinia Stores</strong>, and <strong>Logs</strong>. Defaults are <strong>300</strong> ms and <strong>2</strong> characters.</p><h3 id="search-debounce-ms" tabindex="-1">Search Debounce (ms) <a class="header-anchor" href="#search-debounce-ms" aria-label="Permalink to &quot;Search Debounce (ms)&quot;">​</a></h3><p><strong>Delay after typing stops</strong> before the query applies. The field is marked <strong>100–1000</strong>. The default is <strong>300</strong>.</p><h3 id="minimum-search-length" tabindex="-1">Minimum Search Length <a class="header-anchor" href="#minimum-search-length" aria-label="Permalink to &quot;Minimum Search Length&quot;">​</a></h3><p><strong>Minimum characters</strong> before a new filter runs. The field is marked <strong>1–10</strong>. The default is <strong>2</strong>.</p><p>A shorter non-empty query does not start a new search. The previous result stays until the field is cleared or the query reaches the minimum. An empty field shows the full list. <strong>Network</strong> and <strong>Logs</strong> count the text inside double quotes. <strong>Props</strong> and <strong>Pinia Stores</strong> count the whole field, including the quote characters.</p><hr><h2 id="auto-refresh" tabindex="-1">Auto Refresh <a class="header-anchor" href="#auto-refresh" aria-label="Permalink to &quot;Auto Refresh&quot;">​</a></h2><p><strong>Enable auto refresh</strong> is off by default. <strong>Refresh Interval</strong> appears only while it is on. The default interval is <strong>5 seconds</strong>. The choices are <strong>1 second</strong>, <strong>2 seconds</strong>, <strong>5 seconds</strong>, <strong>10 seconds</strong>, and <strong>30 seconds</strong>.</p><p><strong>Pinia Stores</strong> reloads the store list on that interval while that tab is open and the panel is visible. A tick is skipped while a load is already running. Hiding the panel stops the timer; showing it starts the timer again if the checkbox is still on.</p><p><strong>Props</strong> reloads the component tree on that interval while the panel is visible, and stops while it is hidden. If <strong>10</strong> tree updates arrive within <strong>5 seconds</strong>, further updates are dropped for <strong>10 seconds</strong>. The console says <code>Props update flood detected, entering cooldown</code>. There is no switch for that. Changing the checkbox or the interval also starts a second <strong>Props</strong> timer that keeps running until you leave the <strong>Props</strong> tab, including while the panel is hidden.</p><p><strong>Network</strong> is not on this timer.</p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/qa-tools/docs/options/settings_management.html">Settings management</a></li><li><a href="/qa-tools/docs/options/display_mode.html">Display modes</a></li></ul>',19)])])}const u=t(n,[["render",a]]);export{c as __pageData,u as default};
